initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Subscription ${subscription} 
        with an id set to ${subscription_id}
        and an initial Entity ${entity}
        with an id set to ${entity_id}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Entity by Id with Response Status Code set to 204     and
        Notification with Notification containing entity element set to 'entity-deleted-name-attribute-on-entity-deleted-normalized.json'
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entities/{id}'
        method set to 'DELETE'
        Delete Entity Request with id set to ' ${entity_id}'
}
